app.get('/callback', async (req, res) => {
  const saved = req.session.oauth;
  if (!saved || req.query.state !== saved.state) return res.status(400).send('bad state');
  const tokens = await exchangeCode(req.query.code, saved.verifier); // POST to token endpoint
  const claims = await verifyIdToken(tokens.id_token, saved.nonce);  // JWKS, iss, aud, exp, nonce
  req.session.regenerate(async () => {
    req.session.userId = await upsertUser(claims.iss, claims.sub, claims.email);
    res.redirect('/');
  });
});

